# Cross-check of the main models in R (lme4 / vegan). Author: RNV.
# Input: individuals_clean.csv and fragment-level files produced by 02_analyse_centroid_size_and_wing_shape.py
args <- commandArgs(trailingOnly = TRUE)
base <- if (length(args)) args[1] else "."
suppressPackageStartupMessages({library(lme4); library(vegan); library(MASS)})
d <- read.csv(file.path(base, "outputs", "individuals_clean.csv"))
d$frag <- factor(d$frag); d$season <- factor(d$season); d$year <- factor(d$year)
sink(file.path(base, "outputs", "R_crosscheck_output.txt"))
cat("R", R.version.string, "| lme4", as.character(packageVersion("lme4")), "| vegan", as.character(packageVersion("vegan")), "\n\n")
cat("== Kruskal-Wallis ==\n"); print(kruskal.test(cs ~ frag, d))
cat("\n== Pairwise Wilcoxon (Bonferroni) ==\n"); print(pairwise.wilcox.test(d$cs, d$frag, p.adjust.method = "bonferroni", exact = FALSE))
cat("\n== Individual-level OLS ==\n"); o <- lm(cs ~ log_area + log_iso + elev100, d); print(summary(o)); print(car_vif <- tryCatch(car::vif(o), error = function(e) "car not installed"))
cat("\n== Null LMM, ICC ==\n"); m0 <- lmer(cs ~ 1 + (1 | frag), d, REML = TRUE); vc <- as.data.frame(VarCorr(m0)); print(vc); cat("ICC =", vc$vcov[1] / sum(vc$vcov), "\n")
cat("\n== LMM cs ~ log_area + (1|frag) ==\n"); ma <- lmer(cs ~ log_area + (1 | frag), d, REML = TRUE); print(summary(ma)); print(confint(ma, method = "profile", quiet = TRUE))
cat("\n== LRT area (ML) ==\n"); print(anova(update(m0, REML = FALSE), update(ma, REML = FALSE)))
cat("\n== LMM + season ==\n"); ms <- lmer(cs ~ log_area + season + (1 | frag), d, REML = TRUE); print(summary(ms)); print(anova(update(ma, REML = FALSE), update(ms, REML = FALSE)))
cat("\n== LMM + year ==\n"); my <- lmer(cs ~ log_area + year + (1 | frag), d, REML = TRUE); print(anova(update(ma, REML = FALSE), update(my, REML = FALSE)))
cat("\n== LMM full ==\n"); mf <- lmer(cs ~ log_area + log_iso + elev100 + (1 | frag), d, REML = TRUE); print(summary(mf)$coefficients); print(anova(update(ma, REML = FALSE), update(mf, REML = FALSE)))
cat("\n== LMM disturbance ==\n"); md <- lmer(cs ~ dist_ord + (1 | frag), d, REML = TRUE); print(summary(md)$coefficients)
cat("\n== Fragment-level OLS (n = 9) ==\n"); fl <- aggregate(cs ~ frag + log_area + log_iso + elev100 + dist_ord, d, mean); print(summary(lm(cs ~ log_area, fl))); print(confint(lm(cs ~ log_area, fl)))
cat("\n== Shape: PERMANOVA (adonis2) on Procrustes coordinates ==\n")
P <- read.csv(file.path(base, "outputs", "procrustes_coords.csv")); Y <- as.matrix(P[, grep("^p", names(P))]); set.seed(2026)
print(adonis2(dist(Y) ~ frag, data = P, permutations = 4999))
cat("\n== Shape: betadisper (homogeneity of multivariate dispersion) ==\n"); bd <- betadisper(dist(Y), P$frag); print(anova(bd)); print(permutest(bd, permutations = 999))
cat("\n== Mantel D2 vs geographic distance ==\n")
D2 <- as.matrix(read.csv(file.path(base, "outputs", "mahalanobis_D2_matrix.csv"), row.names = 1)); diag(D2) <- 0
G <- as.matrix(read.csv(file.path(base, "outputs", "geo_distances_table2.csv"), row.names = 1))
print(mantel(as.dist(D2), as.dist(G), permutations = 9999))
cat("\n== MANOVA on 20 shape PCs (Wilks, Pillai) ==\n"); pcs <- read.csv(file.path(base, "outputs", "shape_PCs.csv")); X <- as.matrix(pcs[, 1:20]); fit <- manova(X ~ factor(pcs$frag)); print(summary(fit, test = "Wilks")); print(summary(fit, test = "Pillai"))
sink()
cat("done\n")
